const fs = require('fs');

const [A, B] = fs.readFileSync(0, 'utf8').trim().split(/\s+/).map(Number);

const ana = A % 3;
let beatriz = B % 3;

if (beatriz === ana) {
  beatriz = (beatriz + 1) % 3;
}

for (let chair = 0; chair < 3; chair++) {
  if (chair !== ana && chair !== beatriz) {
    console.log(chair);
    break;
  }
}
